/** 取某字的笔画数；无此字返回 0 */
export function strokeCount(ch) {
  return STROKE_ORDER_INDEX[ch]?.n ?? 0;
}

/** 该字所在的分片文件名；无此字返回 null */
export function strokeShard(ch) {
  const id = STROKE_ORDER_INDEX[ch]?.s;
  return id ? `stroke-data/s${id}.json` : null;
}

